      var h=getHTML(hosts[i]+path, 5000);
      if(h && h.length>500 && h.indexOf('Just a moment')<0 && h.indexOf('access denied')<0 && h.indexOf('站点创建成功')<0) return {html:h, host:hosts[i]};
    }catch(e){}
