function sh(html, sel){
  try{ var m=html.match(new RegExp('<'+sel+'[^>]*>([\\s\\S]*?)</'+sel+'>','i')); return m?m[1]:''; }catch(e){ return ''; }
}
function cleanT(s){ return String(s||'').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim(); }
function panTypeOf(u){
  u=String(u||'').toLowerCase();
  if(u.indexOf('pan.baidu')>=0)return'百度';
  if(u.indexOf('quark')>=0)return'夸克';
  if(u.indexOf('aliyun')>=0||u.indexOf('alipan')>=0)return'阿里';
  if(u.indexOf('xunlei')>=0)return'迅雷';
  if(u.indexOf('drive.uc.cn')>=0||u.indexOf('uc.cn')>=0)return'UC';
  if(u.indexOf('115.com')>=0||u.indexOf('115cdn')>=0)return'115';
  if(u.match(/123(\d{2,4})?\.(com|cn|net)|123pan\.(com|cn)/))return'123';
  if(u.indexOf('cloud.189')>=0)return'天翼';
  if(u.indexOf('caiyun')>=0||u.indexOf('139.com')>=0)return'移动';
  if(u.indexOf('guangya')>=0||u.indexOf('光鸭')>=0)return'光鸭';
  if(u.indexOf('pikpak')>=0)return'PikPak';
  if(u.indexOf('magnet:')===0)return'磁力';
  if(u.indexOf('lanzou')>=0||u.indexOf('蓝奏')>=0)return'蓝奏';
  return'网盘';
}
