  return r[t]!==undefined?r[t]:99;
}
function absURL(base, u){
  u=String(u||'');
  if(!u)return'';
  if(/^https?:\/\//i.test(u))return u.replace(/^\/\//,'https://');
  if(u.indexOf('//')===0)return'https:'+u;
  return base.replace(/\/+$/,'')+'/'+u.replace(/^\//,'');
}
