function stripNoise(t){
  var orig=String(t||'').trim();
  var r=orig
    .replace(/^[【\[]?(?:立即|立刻|马上|火速|超清|高清|蓝光)?(?:播放|观看|看片|点播|追剧)(?:[：:、\s]+)?/,'')
    .replace(/^(?:在线观看|在线播放|免费观看|免费播放)(?:[：:、\s]+)?/,'')
    .trim();
  if(!r||r.length<=1)return orig;
  return r;
}
function pickFromBlock(blk, host, siteId){
  var aM=blk.match(/<a[^>]*href="([^"]*(?:voddetail\/|detail\/id\/|vod\/detail\/|\/book\/)[^"]+)"[^>]*>/i);
  if(!aM){
    aM=blk.match(/<a[^>]*href="([^"]+)"[^>]*>/i);
    if(!aM) return null;
    if(!/\/vod\/|\/book\/|detail|play\//i.test(aM[1])) return null;
  }
  var href=aM[1];
  if(!/^https?:/i.test(href)) href=absURL(host, href);
  var idm=href.match(/voddetail\/(\d+)/)||href.match(/detail\/id\/(\d+)/)||href.match(/vod\/detail\/id\/(\d+)/)||href.match(/\/book\/(\d+)/)||[];
  var id=idm[1]||href;
  var title='';
  var t1=blk.match(/<a[^>]*href="[^"]*"[^>]*title="([^"]*)"/i);
  if(t1) title=t1[1];
  if(!title){ var t2=blk.match(/<img[^>]*alt="([^"]+)"/i); if(t2) title=t2[1]; }
  if(!title){ var t3=blk.match(/<(?:h3|h4|h2|div)[^>]*class="[^"]*(?:title|item-title|search-item-title|video-title)[^"]*"[^>]*>([\s\S]*?)<\/(?:h3|h4|h2|div)>/i); if(t3) title=cleanT(t3[1]); }
  if(!title){ var t4=blk.match(/<a[^>]*>([\s\S]*?)<\/a>/i); if(t4) title=cleanT(t4[1]); }
  title=String(title||'').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim();
  if(!title || title.length>80) return null;
  title=stripNoise(title);
  var pic='';
  var pm=blk.match(/<img[^>]*data-src="([^"]+)"/i)||blk.match(/<img[^>]*data-original="([^"]+)"/i)||blk.match(/<img[^>]*data-lazy-src="([^"]+)"/i)||blk.match(/<img[^>]*src="([^"]+)"/i);
  if(pm){ pic=pm[1]; if(!/^https?:/i.test(pic)) pic=absURL(host, pic); }
  if(pic && (pic.indexOf('gravatar')>=0 || pic.indexOf('t1.svg')>=0 || pic.indexOf('.gif')>=0 && pic.indexOf('lazy')>=0)) pic='';
  return {id:siteId+'_'+id, href:href, title:title, pic:pic};
}
function pickItems(html, host, siteId){
