function panOpenUrl(url, typeKey, pwd){
  url=String(url||''); pwd=String(pwd||'');
  if(/^magnet:/i.test(url)) return 'magnet://'+url.replace(/^magnet:/i,'');
  var t=String(typeKey||'').toLowerCase();
  var mod='';
  if(/baidu|pan\.baidu/i.test(t)||/pan\.baidu\.com/i.test(url)) mod='baiduPan';
  else if(/quark/i.test(t)||/pan\.quark\.cn/i.test(url)) mod='quarkPan';
  else if(/uc/i.test(t)||/drive\.uc\.cn/i.test(url)) mod='ucPan';
  else if(/xunlei/i.test(t)||/pan\.xunlei\.com/i.test(url)) mod='xunleiPan';
  else if(/123/i.test(t)||/123[a-z0-9]*\.(?:com|cn|net)/i.test(url)) mod='pan123';
  else if(/115/i.test(t)||/115\.com/i.test(url)||/115cdn/i.test(url)) mod='pan115';
  else if(/guangya/i.test(t)||/guangya/i.test(url)) mod='guangyaPan';
  else if(/tianyi|189/i.test(t)||/cloud\.189\.cn/i.test(url)) mod='tianyiPan';
  else if(/yidong|mobile|139/i.test(t)||/139\.com/i.test(url)||/caiyun/i.test(url)) mod='yidongPan';
  if(mod){
    return $('hiker://empty#noRecordHistory##noHistory#').rule(function(u, p, m){
      $.require(m).openShare(u, p);
    }, url, pwd, mod);
  }
  return 'copy://'+url;
}

