setPageTitle("123云盘登录");
if (!getItem('pan123_uuid', '')) {
    setItem('pan123_uuid', 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'.replace(/x/g, function() { return (Math.random() * 16 | 0).toString(16); }));
}

d.push({
    title: "账号密码登录",
    url: "hiker://empty",
    col_type: "text_center_1",
    extra: {lineVisible: false}
});
d.push({
    title: "",
    desc: "请输入手机号/邮箱",
    url: "hiker://empty",
    col_type: "input",
    extra: {titleVisible: false, defaultValue: getItem('pan123_passport', ''), onChange: "setItem('pan123_passport',input)"}
});
d.push({
    title: "",
    desc: "请输入密码",
    url: "hiker://empty",
    col_type: "input",
    extra: {titleVisible: false, defaultValue: getItem('pan123_password', ''), onChange: "setItem('pan123_password',input)"}
});
d.push({
    title: "\u2018\u2018\u2019\u2019确认登录",
    url: $().lazyRule(() => {
        let passport = getItem('pan123_passport', '');
        let password = getItem('pan123_password', '');
        if (!passport) { toast('请输入账号'); return 'hiker://empty'; }
        if (!password) { toast('请输入密码'); return 'hiker://empty'; }
        try {
            let configResp = fetch('https://apigate.123795.com/getconfig-api/v1/getconfig?platform=android&version=313&channel=1003&env=');
            if (!configResp) { toast('获取配置失败'); return 'hiker://empty'; }
            let config = JSON.parse(configResp).data;
            let loginData = JSON.parse(fetch(config.interfaceapi.login, {
                headers: {
                    'x-channel': '1003',
                    'user-agent': '123pan/v3.1.3(Android_10;Xiaomi)',
                    'authorization': '',
                    'content-type': 'application/json; charset=UTF-8',
                    'osversion': 'Android_14',
                    'loginuuid': getItem('pan123_uuid', ''),
                    'platform': 'android',
                    'devicetype': '2312DRAABC',
                    'devicename': 'Xiaomi',
                    'host': 'www.123pan.com',
                    'app-version': '312',
                    'x-app-version': '3.1.3'
                },
                body: JSON.stringify({ passport: passport, password: password, type: 1 }),
                method: 'POST'
            }));
            if (loginData.message === 'success') {
                setItem('pan123_authorization', 'Bearer ' + loginData.data.token);
                setItem('pan123_expire_time', loginData.data.refresh_token_expire_time + '');
                toast('登录成功');
                back(true);
            } else {
                toast(loginData.message || '登录失败');
            }
        } catch(e) {
            toast('登录异常: ' + e.message);
        }
        return 'hiker://empty';
    }),
    col_type: "text_center_1",
    extra: {lineVisible: false}
});
setResult(d);
"}]
